		videoPath = "",
		videoType = 0,
		id = 101040101,
		videoId = 0,
		desc = "斯皮尔特计划两年内生产一支能够占领诺伊汉萨的智械军团，由于今天早上的突发事件，计划被提前了。\n让新人们继续执行任务有些太危险，但薇儿丹蒂和奥西里斯都表现出强烈的决意，而且——\n所有智械还有不到20分钟就会被唤醒启动，没有时间等待支援，只能由现场的成员们阻止智械军团的启动了。",
