		videoPath = "",
		videoType = 0,
		id = 101040201,
		videoId = 0,
		desc = "迷铁之家撤走后，被绑在整备室的阿修罗饿得肚子直叫。\n幸好乔林发现了她，给她吃了奶油吐司并为她解开了锁链。\n为了报答乔林，阿修罗自告奋勇要当乔林的保镖。本以为她是在开玩笑的乔林，下一秒就震惊地看见阿修罗把智械当玩具一般肆意蹂躏着。",
