		videoType = 0,
		id = 101040402,
		videoId = 0,
		desc = "修正者们发现了被绑起来的斯皮尔特董事长尤金。\n解救了尤金之后，他愤怒地控诉着哈法斯的背叛和诺维赫的欺骗，强调斯皮尔特变成这样不是自己的责任。\n序小队以保护他的安全作为交换，让他带路前往可以终止【智械军团】启动的地方。\n唯独奥西里斯从尤金身上感觉到有些奇怪的地方……",
