		desc = "斯皮尔特园区中的一座工厂爆炸坍塌，大量失控的人形智械涌出。抵达现场的寒冰小队和前鬼坊、阿波罗会合，一起阻止智械的外泄。\n另一边，伊森在迷铁之家众人面前慷慨陈词，为了积攒和「科尔盖」对抗的力量，绝佳的机会就摆在他们眼前——\n敲晕这些智械然后搬上车带走，用作日后对抗「科尔盖」的“秘密武器”。",
