		id = 101041201,
		videoId = 0,
		desc = "关停反应炉的行动失败，厂房坍塌后跌入废墟中的序小队，发现通讯装置也祸不单行地坏掉了。\n被唤醒的【库什尔方】从天而降，向众人发起攻击……",
