		videoType = 0,
		id = 101050101,
		videoId = 0,
		desc = "「科尔盖」以命令的姿态向深空之眼发来了「以逮捕【迷铁之家】为最优先事项」的指示。\n那样做的话一定会有智械流出园区，伤害到无辜民众——管理员做出自己的判断，无视了「科尔盖」的意志。\n管理员让修正者们不要与【迷铁之家】产生冲突，只要他们也在与智械缠斗。就像利维坦说的那样——\n“总之，就是和那些安保们一起打智械对吧！”",
