		videoPath = "",
		videoType = 0,
		id = 101051001,
		videoId = 0,
		desc = "管理员和修正者们一起对抗着高浓度的骸能冲入了工厂内部。尽管再一次感受到了曾经被拽入源层时的绝望和恐惧，甚至一度失去了意识，但在众人的权钥守护以及鼓励的声音下还是苏醒了过来。\n前鬼坊用彗光导弹轰开一条道路，抵达了与序小队联络中断前她们所在的地下制造间。",
		trigger = {
