	[101051201] = {
		name = "暗影之袭",
		start = 105121001,
		videoPath = "",
		videoType = 0,
		id = 101051201,
		videoId = 0,
		desc = "在序小队的攻势下，【哈法斯】的本体——难以名状的丑陋黑影从装甲中露出来。\n它歇斯底里地奔逃着，但薇儿丹蒂没有放过它的核心——她一剑击碎了那赤色的晶体，彻底终结了这场阴谋的罪魁祸首。\n与此同时，管理员一行人也找到了她们的方位，用权钥打开了源层出口，将她们救了出来。\n会合后的大家还在疑惑究竟是谁使能量反应炉停下时，就遇到了“答案”本人乔林。\n但乔林看到跟修正者们在一起的“尤金”后十分惊讶，知道尤金已死的他大声质问那人是谁。\n噗嗤嗤嗤——\n知道自己的伪装已经败露的诺维赫偷袭了巴德尔，然后消失在了众人的视野中。",
		trigger = {
			1,
			1010512,
			1
		}
	},
	[101051301] = {
		name = "叹息的归途",
		start = 105131001,
		videoPath = "",
		videoType = 0,
		id = 101051301,
		videoId = 0,
		desc = "回到深空之眼，手术后的巴德尔脱离了生命危险，却不知道何时才能醒来。\n奥西里斯恢复意识，但陷入了不愿与任何人交谈的消沉状态。\n在这凝重的氛围中，从另一原质区笹波传来了消息……",
		trigger = {
			1,
			1010513,
			1
		}
	},
