		videoType = 0,
		id = 101060101,
		videoId = 600,
		desc = "古时笹波，有鹤、鸦、鹿、猿、蛇五山神；怒人类之愚昧，山神降下天灾，长达百年。天之子率五神官平息山神之怒，被奉为笹波之尊；五家族轮流治理笹波，开启笹波治世；然而五家逐渐实力失衡，意见失和，笹波暗流涌动，危机四伏……",
