		videoId = 0,
		desc = "众人决定去情报组织「白桦信托」的新据点购买情报，但却意外遇到了被红石河公会威胁的记者莱卡，救下莱卡的同时，塞尔凯特也了解到了浪游城混乱的现状。众人快马加鞭赶往「白桦信托」，遇到了的「白桦信托」的新人赫萝克。但薇儿却在阴差阳错间撞见了被赫萝克保护的涅芙。但实际上涅芙却与塞尔凯特认识，协调之下战斗也得以避免。众人得以知晓涅芙此时被安上了刺杀浪游城集团CEO杰克逊的罪名，遭到通缉的现状。",
