	[104251301] = {
		name = "心火·前",
		start = 425131001,
		videoPath = "",
		videoType = 0,
		id = 104251301,
		videoId = 0,
		desc = "霍德尔的意识在混乱中跳跃着，穿过一段段和巴德尔的回忆，巴德尔曾说过的话在此时成为了指引，最后记忆定格在那枚太阳花吊坠。一直被霍德尔放在身边的小花也开始发挥作用，霍德尔的意识被牵引到曾经见过的那片花园，看到了作为意志投射的小巴德尔，霍德尔交出花朵，突破迷障，从黑暗中醒来。神智清明的霍德尔不再被敌人的信息蛊惑，开始夺回权钥的控制权。",
		trigger = {
			1,
			5310113,
			1
		}
	},
	[104251302] = {
		name = "心火·后",
		start = 425132001,
		videoPath = "",
		videoType = 0,
		id = 104251302,
		videoId = 0,
		desc = "霍德尔重新控制权钥，亲手终结了被困在权钥中的恒常者。战胜敌人后，霍德尔脱力离开权钥，最后在管理员怀中醒来。",
		trigger = {
			1,
			5310113,
			2
		}
	},
	[104251401] = {
		name = "初霁",
		start = 425141001,
		videoPath = "",
		videoType = 0,
		id = 104251401,
		videoId = 0,
		desc = "管理员之前因为握着霍德尔的手险些也被拉入权钥中，但是在霍德尔本能的保护下进入了霍德尔意识中槲寄生花园，又在奈落的干预下回到现实，两人在魔方外目睹了霍德尔与恒常者抗争的过程，直到霍德尔也回到现实。霍德尔醒来后掌握了权钥，但是对恒常者的情况仍然有很多不解之处，但奈落一时也没有答案，只能留待后续研究。",
		trigger = {
			1,
			5310114,
			1
		}
	},
	[104251501] = {
		name = "澄明",
		start = 425151001,
		videoPath = "",
		videoType = 0,
		id = 104251501,
		videoId = 0,
		desc = "两人即将离开科尔盖，因为权钥内有很多重要信息，斯卡雷特希望霍德尔后续能在必要的时候协助科尔盖，霍德尔同意。奈落则察觉到管理员接触过奇械，给了管理员一张收容中心的特殊执法证件，委托管理员以后碰到类似的物品能帮忙留心。事情告一段落，两人终于难得有了放松的时候，一同在街上闲逛时，霍德尔提出希望以后还能继续做管理员的助手，一直向管理员学习。",
		trigger = {
			1,
			5310115,
			1
		}
	},
	[104260101] = {
		name = "山中岁",
		start = 426011001,
		videoPath = "",
		videoType = 0,
		id = 104260101,
		videoId = 0,
		desc = "初到囚云山，学习了一天打算用餐的管理员却得知后土走后无咎和必安已很久没吃过饭，因为两人不能离开囚云山太远，年复一年出现在邻近村镇难免惹人怀疑，同时两人的神能和权钥一体，分开会导致异常，所以也不能单独远行，因此索性不再下山，山中也已经断粮多年。但最终在管理员的说服下，无咎和必安答应陪管理员下山一趟采购食材。",
		trigger = {
			1,
			5330101,
			1
		}
	},
	[104260201] = {
		name = "人烟近",
		start = 426021001,
		videoPath = "",
		videoType = 0,
		id = 104260201,
		videoId = 0,
		desc = "下山路上，管理员向无常双子提出秋霖宫环境清苦，想帮忙装修一下，可没有立刻得到肯定的答复。到山下小镇后，管理员让无咎和必安去闲逛休息，自己去采购食材，却在去集市的途中发现被跟踪。管理员撞破跟踪者，来人竟然是西蒙斯，西蒙斯告诉管理员「白组」被临时调来囚云山保护管理员，此时白泽向西蒙斯发起通讯，镇上发现了居民的尸体。",
		trigger = {
			1,
			5330102,
			1
		}
	},
	[104260301] = {
		name = "风波引",
		start = 426031001,
		videoPath = "",
		videoType = 0,
		id = 104260301,
		videoId = 0,
		desc = "西蒙斯和管理员来到案发现场，白泽告诉两人死者身体内部被骸能侵蚀，但没有发现视骸踪迹。几人交流时无咎和必安悄悄出现在不远处，并单独招呼管理员和她们回山去。拉扯间白泽走了过来，两姐妹只得有些紧张地和白泽互相认识，临走时，白泽却觉得无咎的脸有些熟悉，但没有妄下定论。管理员便跟着无常姐妹回山了。",
		trigger = {
			1,
			5330103,
			1
		}
	},
	[104260401] = {
		name = "问疑踪",
		start = 426041001,
		videoPath = "",
		videoType = 0,
		id = 104260401,
		videoId = 0,
		desc = "管理员和无常姐妹回到秋霖宫，必安开始下厨做饭，管理员在花田里找到了闷闷不乐的无咎，他以为是被白泽的气场吓到，但无咎回避了这个话题。晚上三人一同用餐，管理员随口问起两姐妹今天在镇上的行踪，没想到两人反应异常，管理员猜到或许与命案有关，希望两人能说清楚。",
		trigger = {
			1,
			5330104,
			1
		}
	},
	[104260501] = {
		name = "察旧情",
		start = 426051001,
		videoPath = "",
		videoType = 0,
		id = 104260501,
		videoId = 0,
		desc = "必安告诉管理员，山下的死者确实和她们有关。原来必安和无咎都是跟随后土学习过的送葬人，今天在山下看到了那个被侵蚀的平民，便为他举行了葬仪，但是两人没有注册过正式身份，看到科尔盖调查一时心慌，才有了这场乌龙。晚上管理员收到白泽通讯，正想向她解释此事，白泽却告诉管理员她查到无咎和必安的身份都有问题，其中必安曾经被医院宣告死亡，而同一天无咎的养父变成侵蚀种，在这场意外中她涉嫌杀害了身为人类的养母，后又越狱。两人谈话时，管理员室外传来响动，但等他推开门已经空无一人。",
		trigger = {
			1,
			5330105,
			1
		}
	},
	[104260601] = {
		name = "饰玉堂",
		start = 426061001,
		videoPath = "",
		videoType = 0,
		id = 104260601,
		videoId = 0,
		desc = "管理员担心无咎听到了自己和白泽的对话，但无咎表现一切如常，管理员也觉得眼下不是提这件事的时候，便暂时放下此事，重新提起装修秋霖宫的计划。没想到这次得到了必安的大力支持，于是在几人的忙碌下，秋霖宫一天天地变化起来，氛围似乎也越来越融洽。但是在某一天的晚饭时，几人由菜色谈到必安的童年，无咎奇怪为什么必安童年幸福却很少听她提起也没见她回家，在回忆和追问中终于按捺不住情绪的必安说自己当年突然觉醒但却迅速陷入衰弱，自己被宣告「死亡」后，虽然被后土所救，但从此告别了家人，她想知道与自己神能相连的无咎同一天发生了什么。",
		trigger = {
			1,
			5330106,
			1
		}
	},
	[104260701] = {
		name = "起沉疴",
		start = 426071001,
		videoPath = "",
		videoType = 0,
		id = 104260701,
		videoId = 0,
		desc = "必安在意无咎这么多年都隐瞒了这件大事，无咎则以为必安在责怪自己。必安回到房间，无咎在激动中冲出房门消失不见，晚餐不欢而散。必安本以为无咎躲到了花田地窖里，打算第二天再好好交流，没想到此必安和管理员看到了无咎留下的信，她独自下山了。管理员安抚住必安，表示自己会下山寻找无咎。无咎找到了当年在案件中指认自己的养父母的女儿余秧，希望她能重新向警方交代实情，说明她当年并没有看到案发全程，但却被拒绝，余秧再次报警，心灰意冷的无咎被带走。",
		trigger = {
			1,
			5330107,
			1
		}
	},
	[104260801] = {
		name = "归路险",
		start = 426081001,
		videoPath = "",
		videoType = 0,
		id = 104260801,
		videoId = 0,
		desc = "几位警官押着无咎离去，却在路上遇到剑奴。无咎此时远离必安，独自启动权钥会陷入失控，当年的惨案便因此酿成。但犹豫间一位警官为保护身为嫌疑犯的她而受伤，无咎终于启动权钥，击败剑奴。管理员和白泽赶到时，无咎已经昏迷过去，她体内神能暴动无法治疗，管理员送她回囚云山。管理员从山脚背着无咎上山，一边听她断续言说着心中的痛苦，一边安抚着她。",
		trigger = {
			1,
			5330108,
			1
		}
	},
	[104260901] = {
		name = "伤花剑",
		start = 426091001,
		videoPath = "",
		videoType = 0,
		id = 104260901,
		videoId = 0,
		desc = "管理员背着无咎回到山上，发现必安果然已经陷入虚弱之中。管理员安顿好两人，但无咎在此时再次暴动，必安为保护管理员在花田中和无咎激战，眼看要支撑不住时，管理员一句「不是你的错」点破无咎心结，无咎消失在花田中。管理员与必安谈心，必安真正在意的事姐姐作为自己最亲近的人，却没有足够相信自己，有所隐瞒，但现在也明白自己应该用更包容的态度对待无咎。",
		trigger = {
			1,
			5330109,
			1
		}
	},
	[104261001] = {
		name = "点灵犀",
		start = 426101001,
		videoPath = "",
		videoType = 0,
		id = 104261001,
		videoId = 0,
		desc = "管理员来到花田，播放了一段先前装修秋霖宫时几人其乐融融的录像，开导无咎真正的家人无论什么时候都应该携手站在一起。无咎哭着说自己做错了很多，但是管理员都以包容理解对待，无咎终于现身扑到管理员怀中，必安也来到花田，两人心结化解，重归于好。晚上管理员被压醒发现无常姐妹竟然跑来了自己床上，并声称是管理员进错房间，换房间被拦下后，管理员只得躺下，给两人讲起故事，三人一同睡去。",
		trigger = {
			1,
			5330110,
			1
		}
	},
	[104261101] = {
		name = "春又来",
		start = 426111001,
		videoPath = "",
		videoType = 0,
		id = 104261101,
		videoId = 0,
		desc = "管理员醒来后在厨房找到了正在做早餐的无常姐妹，无咎和必安已经正式把管理员当作是家人，几人一起笑笑闹闹地做饭。饭后三人一同来到花田，修整昨天被打坏的田地，无咎意识到有许多人在支持着自己，有了再次面对过去，走向未来的勇气，秋霖宫重归美好平静。",
		trigger = {
			1,
			5330111,
			1
		}
	},
	[104150101] = {
		name = "踏访岱屿",
		start = 415011001,
		videoPath = "",
		videoType = 0,
		id = 104150101,
		videoId = 0,
		desc = "执明受邀来到岱屿参加会议，然而会议却因「参会专家未到齐」暂未召开。在接待员的建议下，执明打算趁这个时间去仔细了解岱屿的现状。",
		trigger = {}
	},
	[104150201] = {
		name = "紧急撤离",
		start = 415021001,
		videoPath = "",
		videoType = 0,
		id = 104150201,
		videoId = 0,
		desc = "执明发现主岛有许多视骸，然而科尔盖却没有检测到任何骸能异常。\n从主岛返回的执明在会议上说明了她对现状的判断，并在天工司负责人石英的支持下，开始了撤退工作……",
		trigger = {}
	},
	[104150301] = {
		name = "云端二重",
		start = 415031001,
		videoPath = "",
		videoType = 0,
		id = 104150301,
		videoId = 0,
		desc = "来到主岛某处的执明击败了化作自身形貌的云雾，并回收了部分云团作为样本。此时岱屿各项数据已临近极限，科尔盖强制执行了撤离方案。\n执明回到实验室开始研究收集到的云团样本，结果数据令她感到不可思议……",
		trigger = {}
	},
	[104150401] = {
		name = "暂时的平静",
		start = 415041001,
		videoPath = "",
		videoType = 0,
		id = 104150401,
		videoId = 0,
		desc = "执明一边击退着四周源源不断的视骸与智械，一边用维修工具箱的工具修复着地质稳定仪。情况危急之时，执明完成了地质稳定仪的修复工作，同时科尔盖的支援及时赶到。\n岱屿空岛的情况趋于稳定，然而主岛的骸能反应却消失得无影无踪……",
		trigger = {}
	},
	[104150501] = {
		name = "风波初定",
		start = 415051001,
		videoPath = "",
		videoType = 0,
		id = 104150501,
		videoId = 0,
		desc = "执明终于在主岛发现了诡异云雾的本体，与羲和联手准备将它封印。然而云雾还是逃离了封印，离开了岱屿主岛。虽然还有许多未解之疑，但至少现在岱屿安全了。",
