	[910102011] = {
		name = "醒岁知新",
		start = 910109001,
		videoPath = "",
		videoType = 0,
		id = 910102011,
		videoId = 0,
		desc = "来自虚恒的修正者金乌，为完成羲和老师的任务——寻找能净化视骸「夕」的人，而开始一场下山修行历练。\n修行途中，因她被「魑魅」打晕，意外来到艾因索菲，与管理员邂逅后，被深空之眼收留。\n为继续完成老师布置的任务，她需要先返回虚恒，却因原质区转移审批流程过长而滞留艾因索菲。\n管理员通过与金乌交流得知，「夕」虽然被封印在玩偶内，但并不稳定，需要她经常加强「夕」的封印。",
		trigger = {}
	},
	[910103011] = {
		name = "新禧八珍",
		start = 910110001,
		videoPath = "",
		videoType = 0,
		id = 910103011,
		videoId = 0,
		desc = "深空之眼主管财务的猫型AI弥年年，为推进大国主新产品「欧气检测机」的研发，试图通过拓展新业务线的方式重新获得被休否决掉的经费申请。\n经调查，她发现目前艾因索菲缺少适口的异域特色菜品，但由于盖亚严格的原质区入境管理，寻找一位擅长异域菜品的厨师非常艰难。\n同时，打算做虚恒菜的金乌在出门买食材时，刚好看到深空之眼第九部门举行主题广场方案征集大赛，为了获取大赛奖品中的巨型玩偶，她以虚恒著名节日「醒岁节」为主题，报名参与了活动，但对于如何在艾因索菲展现虚恒独特的「云歌石科技」文化仍一筹莫展。\n两拨人在返回深空之眼时偶遇，交流了彼此的想法，为实现共同目标，弥年年与金乌一拍即合，白天设计主题广场策划案，晚上研究虚恒菜品。\n在多次尝试下，新菜品终于通过艾因索菲美食协会的审核，春节饭堂「新禧八珍」正式开张，「欧气检测机」的经费申请也画上了一个完美的句号。",
		trigger = {}
	},
	[910104011] = {
		name = "霞焰星评",
		start = 910111001,
		videoPath = "",
		videoType = 0,
		id = 910104011,
		videoId = 0,
		desc = "尽管研制虚恒菜品的途中取得了开门红，但「醒岁节」主题广场设计方案进度依然停滞不前。\n后来，经管理员的引导，大家终于找到适合在艾因索菲展现醒岁节文化的布局方法，后来，方案成功通过。\n金乌为了让主题广场表现锦上添花，她前往市场，购买了制作烟花的相关材料……",
		trigger = {}
	},
	[910105011] = {
		name = "醒岁除夕（战前）",
		start = 910112001,
		videoPath = "",
		videoType = 0,
		id = 910105011,
		videoId = 0,
		desc = "金乌和管理员将制作好的巨型烟花筒搬运到广场的中央后，遇到了正在布置「醒岁节」主题广场的负责经理。\n经理告知二人主题广场大受欢迎，奖品在1楼存放，二人在取件途中，同时收到羲和老师寄来的新年贺礼，拆礼盒时，金乌发现「夕」的封印松动了，「夕」从中逃离，并在广场内大肆捣乱。\n为了让「夕」重回封印，大家赶往了「夕」所在的地方，准备合力击败「夕」。",
		trigger = {}
	},
	[910105012] = {
		name = "醒岁除夕（战后）",
		start = 910112097,
		videoPath = "",
		videoType = 0,
		id = 910105012,
		videoId = 0,
		desc = "经大家合力努力后，最终击败了「夕」，「夕」被重新封印回玩偶内，意外风波终于结束，一切重回正轨。",
		trigger = {}
	},
