	[103210101] = {
		name = "探查顽疾",
		start = 321011001,
		videoPath = "",
		videoType = 0,
		id = 103210101,
		videoId = 0,
		desc = "伊里伽尔前往富人区参加心理互助会，佯装被对方诱骗，顺利找到了奥蒂斯的藏身之处。奥蒂斯匆忙逃窜，伊里伽尔则被视骸所阻挡，此时守在外面的薇儿与奥西里斯也赶来支援。",
