			1,
			1032101,
			1
		}
	},
	[103210201] = {
		name = "多方会诊·前",
		start = 321021001,
		videoPath = "",
		videoType = 0,
		id = 103210201,
		videoId = 0,
		desc = "奥蒂斯从追捕中逃脱，管理员等人察觉到建筑内还有另外两个出口，决定分头搜寻。管理员与涅赫贝特并未在下水道有所收获，然而薇儿等人却在实验室遭遇了视骸袭击。",
		trigger = {
			1,
			1032102,
			1
		}
	},
	[103210202] = {
		name = "多方会诊·后",
		start = 321022001,
		videoPath = "",
		videoType = 0,
		id = 103210202,
		videoId = 0,
		desc = "伊里伽尔等人在奥蒂斯的客厅找到了暗室，然而奥蒂斯已经通过暗室的传送装置逃离。就在奥蒂斯传送至下水道想要离开时，埋伏在下水道的管理员从身后将他一举拿下。",
		trigger = {
			1,
			1032102,
			2
		}
	},
	[103210301] = {
		name = "「钓鱼执法」",
		start = 321031001,
		videoPath = "",
		videoType = 0,
		id = 103210301,
		videoId = 0,
		desc = "管理员与涅赫贝特设计从奥蒂斯口中问出情报，得知智骸想要复活天灾种——会使得盖亚某个系统失效的强大视骸。",
		trigger = {
			1,
			1032103,
			1
		}
	},
	[103210401] = {
		name = "指间的希望",
		start = 321041001,
		videoPath = "",
		videoType = 0,
		id = 103210401,
		videoId = 0,
		desc = "时间回到几天前，奥西里斯想通过神秘镰刀寻找冥王的下落未果，只能寄希望于从奥蒂斯与智骸身上找线索。同一时间，梵天为了净土计划，独自回到第一纪元。",
		trigger = {
			1,
			1032104,
			1
		}
	},
	[103210501] = {
		name = "追加下注",
		start = 321051001,
		videoPath = "",
		videoType = 0,
		id = 103210501,
		videoId = 0,
		desc = "执明安慰管理员，事态尚未发生，不急于用应急手段联系梵天。管理员来到阿卡德公会，委托伊里伽尔靠灵魂痕迹寻找冥王，并为她将辅助智械奈奈和奈提升级。",
		trigger = {
			1,
			1032105,
			1
		}
	},
	[103210601] = {
		name = "消失的你",
		start = 321061001,
		videoPath = "",
		videoType = 0,
		id = 103210601,
		videoId = 0,
		desc = "为奈奈升级时，管理员再次见到了诗蔻蒂，诗蔻蒂突然模糊地预言了管理员的死兆，希望管理员不要去外面。管理员与薇儿、奥西里斯安慰了诗蔻蒂，决定更小心地实行计划。",
		trigger = {
			1,
			1032106,
			1
		}
	},
	[103210701] = {
		name = "盘根错节",
		start = 321071001,
		videoPath = "",
		videoType = 0,
		id = 103210701,
		videoId = 0,
		desc = "管理员找到吉维卡，想问出联合仲裁在地下排水网道中的未监管施工情况。涅赫贝特也向曼达维亚逼问出了地下网道的地图。而在同一时间，奥蒂斯从监狱逃离，跑入了地下网道里。",
		trigger = {
			1,
			1032107,
			1
		}
	},
	[103210801] = {
		name = "聚焦点",
		start = 321081001,
		videoPath = "",
		videoType = 0,
		id = 103210801,
		videoId = 0,
		desc = "伽梨与奥西里斯来到无限格斗之夜的海选赛决赛，希望找到罗波那，没想到罗波那堂而皇之地登上舞台。另一边逃跑的奥蒂斯也等来了巴钦出现救援，然而一切都是为巴钦设下的圈套。",
		trigger = {
			1,
			1032108,
			1
		}
	},
	[103210901] = {
		name = "一步之遥",
		start = 321091001,
		videoPath = "",
		videoType = 0,
		id = 103210901,
		videoId = 0,
		desc = "通过让特工假扮奥蒂斯，科尔盖成功将巴钦诱入陷阱。然而基维塔巴突然被异象所笼罩，罗波那所在的会场爆发了猛烈的震动，地下网道的陷阱也被震动破坏，巴钦顺利脱身。",
		trigger = {
			1,
			1032109,
			1
		}
	},
	[103211001] = {
