		videoPath = "",
		videoType = 0,
		id = 103211001,
		videoId = 0,
		desc = "奥西里斯从场馆废墟中爬出，发现馆内所有人都已经倒下。场馆外的基维塔巴遇到视骸袭击，情况一片混乱，通讯也彻底断绝。奥西里斯与伽梨汇合后便去抵挡视骸，帮助科尔盖保护民众。",
