		desc = "通过暗道，山洞内是一片开阔的场地，其中有一根贯通的冰柱，长琴则被封于冰柱之内，只能言语，无法行动。长琴早年铸剑时太虚能量入体，只能以冰牢压制，保全性命。常曦来此，是想用尚在长琴手中的神剑「玄问」破开虚空，直达大荒去探明情况。但只有剑主才能驾驭神剑，而唯有望舒曾在百年前用过玄问，但望舒来去无踪，已许久无人见过。因管理员提到望舒的名字，常曦才会带他同来。但管理员不知望舒究竟在哪里，也不愿轻易说出与诺尔薇有关的信息，正当他想要怎么解释时，一个名为相柳的不速之客来到，原来昭黎山的血案是他酿成，他称工坊中用剑的荒兽为「剑奴」，因剑奴被常曦所杀，他前来寻仇。",
