		videoId = 0,
		desc = "常曦出外与相柳力战，但对方同样能使用太虚能量，且实力强大，常曦渐渐不敌。未免出现意外，长琴决定帮助常曦，请管理员从一处暗格中为她取来一个剑匣。管理员拿来剑匣，没想到剑匣刚放好便一触即开，同时传出一声琴音，而这琴音似乎能增强常曦的力量。长琴对于剑匣在管理员手中打开颇为惊疑，但眼下无暇他顾，长琴只好先按下此事，打算破开冰牢用剑匣给常曦助战，但此举会危及她的性命，被管理员拦住。正在两难之间，匣中玄问飞起，望舒来到，执剑逼退相柳。",
