		videoType = 0,
		id = 103240701,
		videoId = 0,
		desc = "管理员和金乌来到一片花田中的陵宫，金乌说这就是后土和无常姐妹的居所「秋霖宫」，同时告诉管理员姐妹中黑发的是无咎，白发的是必安。但两人并没在这里看到无常姐妹，这时墙壁裂开，必安从地下的升降梯跑出来，撞见两人。管理员这才知道刚刚穷奇异动，她和无咎在下方地牢内处理，无咎现在还被困在地牢中。必安打算去地牢机关主控室，管理员却让她和金乌去找无咎，自己监控机关。",
