		desc = "金乌又来到重明所在的工地，得知重明此时仍没有主意，恰好此时舆昊也带人来到。舆昊知道重明想保下工地，考验了一下她的知识和想法，重明过关后舆昊才放心把项目交给重明一试，离开了。但如何保下工地，重明还是没有好办法，金乌索性让她暂时转移注意力，教重明打起弹珠。没想到重明却好像在打弹珠的过程中想到了解决眼前问题的办法。",
