		videoType = 0,
		id = 103240901,
		videoId = 0,
		desc = "重明带着方案去找舆昊，金乌准备回旸山，大荒即将解封的消息也在此时公布。来到大槐树村，金乌发现这里正在庆祝大荒回归，原来洪村长所说的故乡就是大荒。金乌因为之前说要去良工集团帮村民反映情况，被村民当成促成此事的人，受到热烈欢迎。金乌回到若木宫，才看到羲和也回来了，羲和问她下山一趟的收获，金乌意识到了其他人的成长，感觉自己似乎在大事频发的当下有些落后了。另一边重明的方案却因为工程量浩大被舆昊按了下去。",
