		videoType = 0,
		id = 103241001,
		videoId = 0,
		desc = "管理员在囚云山学习机关进度很快，也和无常姐妹渐渐熟络起来。这天管理员在和孟章通话同步进度时逛进一间杂物间，发现墙上挂着一对宝剑。管理员问无常姐妹这是不是神剑，无常姐妹说是栖幽的仿品，管理员却觉得没这么简单，后土去了大荒，不会不留后手，便让姐妹用一用这对剑，两人各舞一遍没有异样，管理员让她们各拿一把共练。",
