		videoPath = "",
		videoType = 0,
		id = 103241201,
		videoId = 0,
		desc = "金乌御剑带着管理员来到昆仑，两人进入冰涧见到长琴。长琴看出金乌使用过长阳，三人交谈间孟章传讯说混沌也开始异动，此时望舒提前打开太虚通道，管理员意识到那边情况不好，叮嘱金乌对眼下的情况要有自己的主见后，匆忙进入通道。金乌不知自己该不该去帮别人的忙，长琴对她讲述了羲和年轻时犯错的故事，并告诉她羲和就是常曦，只为了保护她的积极性才改换面目，羲和也早就看好她做长阳剑主。金乌如梦初醒，明白了老师的苦心，告别长琴御剑飞往南交。",
