		desc = "秋霖宫内，无咎守着对接机关，必安在地牢与荒兽周旋。但对接流程突然暂停，无咎还没弄清状况，地牢中穷奇冲破封印，必安让无咎封锁升降梯，无咎却跑了下去。两人一同逃离地牢后，无咎意识到地牢已经关不住穷奇，她拿出「仿品」栖幽，说服必安与自己再尝试一次使用双剑，这次两人同心合力，双剑果然散发出光彩，但这也意味着后土留下的是真品，自己拿走了仿品。",
