		videoPath = "",
		videoType = 0,
		id = 103241701,
		videoId = 0,
		desc = "羲和金乌消灭混沌，羲和说混沌已除，金乌可以出师下山了。意识到自己真的已经成长的金乌反倒感伤起来。金乌拿了个终端给羲和，羲和正式传长阳剑于金乌，金乌叩首拜别羲和，御剑下山。到山下的大槐树村，金乌告诉村民大荒回归与自己无关，她不能抢功，但现在自己会帮大家去看看大荒，平定那里的危险，村民们觉得金乌似乎不同了，真有了大侠的模样。",
