		id = 103245201,
		videoId = 0,
		desc = "望舒问管理员为什么不考虑共工的提议，荒兽是杀不尽的。管理员说人类向来都是在挣扎中求生，挑战不可能的困难，即便要妥协，也是最后一步。何况盖亚属于人类，要走也只能是外来者走，望舒理解了管理员的立场，表示如有机会杀了共工会告诉管理员。两人继续上山。",
