		desc = "管理员和望舒进入秋霖宫机关室，管理员启动机关，太虚在面前展开，这便是当初隔绝两地的方法。管理员完成操作，对接顺利进行，两人正准备就此从这一侧走回虚恒，但庚辰的封印锁链从虚空中显现，拦停了两侧大陆的对接。望舒尝试用玄问攻击，但没有作用。眼看要成死局，一条金龙幻影横渡太虚而来，劈碎了封印锁链。",
