		videoType = 0,
		id = 103245602,
		videoId = 0,
		desc = "在赶来的金乌和无常姐妹等人的协助下，荒兽被逼退，剑门关被成功守住。但管理员和望舒同样不在剑门关，孟章迅速安排寻找，又和秋丹对接了两地重连的事宜，布置边境哨卡，以免虚恒那边有人误入大荒。金乌听说暂时两地还不能流通，拿出大槐树村的平安符，说村民们可能要失望了。秋丹看到平安符却湿了眼眶，原来他的祖上便和大槐树村有亲，如今后人终于有了相见的机会。",
