		videoPath = "",
		videoType = 0,
		id = 103245702,
		videoId = 0,
		desc = "管理员在沙滩醒来，看到身旁的望舒。望舒告诉管理员，这里是他的意识空间。对接之后他便昏了过去，她带管理员来了瑶池。现在管理员的意识被太虚能量侵蚀，如果不能抹除，他就会死。离开太虚空间的办法是三个小时内掌握承钧，而承钧就是管理员一直背着的剑匣，他自己便是承钧剑主。像当初在客栈一样，望舒开始带领管理员练剑，一遍又一遍，管理员逐渐领悟了其中玄机，就在他似有所感时，望舒从月中抽出长剑，劈开虚空，管理员和望舒一同在瑶池醒来。",
