		desc = "为现状感到慌张的尤金来到中控室，希望夺取所有智械的控制权，并与他的神秘合作者诺维赫产生争执。虽然尤金自以为成功夺取控制权，却被诺维赫反杀。与此同时，序小队也从乔林口中得知了工厂出现的问题，正当几人想将了解情况的乔林护送离开时，迷铁之家的众人堵住了去路。",
		trigger = {
			1,
			1030408,
			1
		}
	},
	[103040802] = {
		name = "帷幕之后·后",
		start = 304082001,
		videoPath = "",
		videoType = 0,
		id = 103040802,
		videoId = 0,
		desc = "在序小队战斗的同时，迷铁之家的领袖伊森与他的下属零一也在某处观察着，两人感慨于修正者的战斗力，并开始了自己的盘算。",
		trigger = {
			1,
			1030408,
			2
		}
	},
	[103040901] = {
		name = "迷铁之家·前",
		start = 304091001,
		videoPath = "",
		videoType = 0,
		id = 103040901,
		videoId = 0,
		desc = "残次品战斗智械无法抵挡序小队，于是奥利海姆决定亲自上阵。",
		trigger = {
			1,
			1030409,
			1
		}
	},
	[103040902] = {
		name = "迷铁之家·后",
		start = 304092001,
		videoPath = "",
		videoType = 0,
		id = 103040902,
		videoId = 0,
		desc = "发现正面不是对手之后，奥利海姆利用薇儿经验不足的冒进，用闪光弹带着手下逃离现场。众人追击时遇到智械包围，好在乔林通过指令关停了智械。经过商议，休认为生产异常智械可能是为了破坏文明稳定，必须加以制止。她决定让阿修罗护送乔林离开，序小队则接过具有乔林权限的终端，前去关闭所有智械。",
		trigger = {
			1,
			1030409,
			2
		}
	},
	[103041001] = {
		name = "敌对修正者",
		start = 304101001,
		videoPath = "",
		videoType = 0,
		id = 103041001,
		videoId = 0,
		desc = "前鬼坊与阿波罗接到管理员命令，前去接应阿修罗与乔林，两人却在厂区内遇到了一位并不怎么聪明的神秘修正者索贝克，他似乎并不知道自己的责任，而是加入了迷铁之家，鲁莽地对两人发动攻击。",
		trigger = {
			1,
			1030410,
			1
		}
	},
	[103041101] = {
		name = "与狼共舞",
		start = 304111001,
		videoPath = "",
		videoType = 0,
		id = 103041101,
		videoId = 0,
		desc = "诺维赫在中控室与伊森会面，并威胁他去对付修正者，伊森口是心非地答应下来。深入工厂的序小队找到了迷铁之家的藏身处，与奥利海姆和零一发生了冲突。",
		trigger = {
			1,
			1030411,
			1
		}
	},
	[103041201] = {
		name = "短兵相接·前",
		start = 304121001,
		videoPath = "",
		videoType = 0,
		id = 103041201,
		videoId = 0,
		desc = "在零一与奥利海姆不敌众人之后，伊森现身，并向几人提出赌斗，败者自行离开。考虑到罗斯塔赫人对赌斗的遵守程度与双方人数差距，休接受了对方提议，三人与似乎非常自信的伊森展开较量。",
		trigger = {
			1,
			1030412,
			1
		}
	},
	[103041202] = {
		name = "短兵相接·后",
		start = 304122001,
		videoPath = "",
		videoType = 0,
		id = 103041202,
		videoId = 0,
		desc = "在势均力敌地交手几个回合之后，伊森意外地向几人投降，并带着迷铁之家成员迅速离开。尽管看出伊森另有打算，但序小队的重点还是解决智械危机上，于是继续向中控室进发。已经潜入中控室的巴德尔调出计划，侵入了中控台，希望与序小队汇合，然而她却发现工厂的智能终端哈法斯其实有自己的智能，随后与众人失去联系。",
		trigger = {
			1,
			1030412,
			2
		}
	},
	[103050101] = {
		name = "临阵决断·前",
		start = 305011001,
		videoPath = "",
		videoType = 0,
		id = 103050101,
		videoId = 0,
		desc = "在同一时间，管理员与前方各小队都失去了联系，并从科尔盖口中得知工厂内已经出现大批失控的战争智械。焦急的管理员决定亲自上阵，并说服霍德尔同意他的决定。在与大国主汇合准备出发时，几人却在深空之眼受到了服务智械的袭击。",
		trigger = {
			1,
			1030501,
			1
		}
	},
	[103050102] = {
		name = "临阵决断·后",
		start = 305012001,
		videoPath = "",
		videoType = 0,
		id = 103050102,
		videoId = 0,
		desc = "解决失控的智械之后，霍德尔与提尔等人表示自己将会守住深空之眼，让管理员安心去前方支援。",
		trigger = {
			1,
			1030501,
