		videoType = 0,
		id = 103050401,
		videoId = 0,
		desc = "管理员与大国主抵达了工厂外围，现场的科尔盖正与智械交战。在科尔盖挤出的炮火支援下，管理员成功突入了园区内。",
		trigger = {
