		videoPath = "",
		videoType = 0,
		id = 103050402,
		videoId = 0,
		desc = "与雷小队和阿修罗等人会合后，管理员得知乔林打算冒风险回去，用最后方案关停所有园区生产的智械。最终管理员尊重了乔林的意见，让阿修罗去协助他。管理员自己则与雷小队等人进入工厂，寻找到序小队向下离开的电梯井，并在旁边意外地发现了尤金。",
