		videoType = 0,
		id = 103050501,
		videoId = 0,
		desc = "与视骸激战过后，薇儿和奥西里斯吸引了哈法斯的注意，让休救出了昏迷的巴德尔。然而就在几人准备离开时，巨型智械突然启动，击碎了众人的退路。",
