		videoType = 0,
		id = 103050702,
		videoId = 0,
		desc = "在管理员的支援下，众人合力击碎了哈法斯的机甲，它的本体也被众人共同解决。另一边，乔林也顺利关闭智械，让危机告一段落。就在众人准备离开时，伪装成尤金的诺维赫发动偷袭，被识破后逃离，至此，工厂内的所有危机都告一段落。",
