		start = 926011001,
		videoPath = "",
		videoType = 0,
		id = 926011001,
		videoId = 0,
		desc = "塞尔凯特告诉管理员和薇儿深空之眼即将开展团建，然而作为团建目的地的度假小岛却突发异象。于是管理员、薇儿丹蒂、塞尔凯特和执明组成了调查团前往岛上调查，却遇到了未曾见过的生物。",
		trigger = {
			1,
			5270201,
			1
		}
	},
	[926021001] = {
		name = "女主登场！",
		start = 926021001,
		videoPath = "",
		videoType = 0,
		id = 926021001,
		videoId = 0,
		desc = "自称尼娅的神秘少女出手帮调查团消灭了来袭的魔物，并向众人介绍了这座小岛——卡达斯王国的现状。管理员从尼娅口中得知要想让这里恢复正常需要消灭城堡内的邪龙，正想继续提问，肚子却开始咕咕直叫。尼娅告诉大家在这座小岛上「饿了就会变弱」，见大家也不愿意吃下自己做的饭，于是带大家去往了泳者公会，管理员在此开始做起第一道料理。",
		trigger = {
			1,
			5270202,
			1
		}
	},
	[926031001] = {
		name = "冒险伊始",
		start = 926031001,
		videoPath = "",
		videoType = 0,
		id = 926031001,
		videoId = 0,
		desc = "管理员做的烤鱿鱼非常好吃，尼娅也因此说出了更多和邪龙有关的情报，并告诉众人要击败邪龙必须拥有一支强大的泳者小队。于是在塞尔凯特的提议下，泳者公会正式被改造成饭堂，用以招募泳者。",
		trigger = {
			1,
			5270203,
			1
		}
	},
	[926041001] = {
		name = "路遇伙伴",
		start = 926041001,
		videoPath = "",
		videoType = 0,
		id = 926041001,
		videoId = 0,
		desc = "一行人前往海滩开始收集食材，却遇到了被宝箱怪吃掉的白发双马尾美少女——大国主。在将她救出来后，塞尔凯特将她邀请到了饭堂，准备将她招募入队。",
		trigger = {
			1,
			5270204,
			1
		}
	},
	[926051001] = {
		name = "探访密林·前",
		start = 926051001,
		videoPath = "",
		videoType = 0,
		id = 926051001,
		videoId = 0,
		desc = "尼娅再次检查大家的战斗力数值，发现有了比较大的提升，同时为了让管理员开发新菜，将管理员一行人带到了丛林之中。",
		trigger = {
			1,
			5270205,
			1
		}
	},
	[926052001] = {
		name = "探访密林·后",
		start = 926052001,
		videoPath = "",
		videoType = 0,
		id = 926052001,
		videoId = 0,
		desc = "管理员正在整理菜谱的思路，塞尔凯特却发现尼娅似乎消失了，众人连忙开始寻找尼娅。最后发现尼娅正呆在一棵树旁看对面的野猪聚落，尼娅说她是跟着一头密林凶豚来到这里的，这里的魔物会自己寻找瓜果蔬菜收集到一起，我们也可以借用一些拿来做饭。",
		trigger = {
			1,
			5270205,
			2
		}
	},
	[926061001] = {
		name = "突入城堡·前",
		start = 926061001,
		videoPath = "",
		videoType = 0,
		id = 926061001,
		videoId = 0,
		desc = "尼娅告诉大家的战斗力终于突破了战斗力探测器的上限，可以前往她也没有探索过的区域——最危险的古堡。",
		trigger = {
			1,
			5270206,
			1
		}
	},
	[926062001] = {
		name = "突入城堡·后",
		start = 926062001,
		videoPath = "",
		videoType = 0,
		id = 926062001,
		videoId = 0,
		desc = "尼娅在混战中被魔物带走，大家在墙角找到了追过去的执明，然而执明并没有追上尼娅，同时告诉大家这个城堡还有很多机关，非常危险。同时塞尔凯特发现城堡的大门也被关上了，众人只能继续前进。",
		trigger = {
			1,
			5270206,
			2
		}
	},
	[926071001] = {
		name = "邪龙出没·前",
		start = 926071001,
		videoPath = "",
		videoType = 0,
		id = 926071001,
		videoId = 0,
		desc = "众人探索到了城堡的最高处，然而这里即没有邪龙也没有尼娅，只有一个闪闪发光的秘宝。薇儿正准备上前拿取，尼娅从宝座后走出，坐在了宝座上。不等管理员问为什么，尼娅突然化身邪龙，与大家展开战斗。",
		trigger = {
			1,
			5270207,
			1
		}
	},
	[926072001] = {
		name = "邪龙出没·后",
		start = 926072001,
		videoPath = "",
		videoType = 0,
		id = 926072001,
		videoId = 0,
		desc = "面对尼娅的突然发难，管理员和邪龙冒险团挺身而出与尼娅定下三场胜负，并立下赌约。而第一场对决，正是全力以赴的战斗。",
		trigger = {
			1,
			5270207,
			2
		}
	},
	[926081001] = {
		name = "一决胜负！·前",
		start = 926081001,
		videoPath = "",
		videoType = 0,
		id = 926081001,
		videoId = 0,
		desc = "第一场战斗，尼娅落败，然而她却很开心。尼娅提议第二场战斗为料理对决，管理员欣然接受，并邀请薇儿来当裁判。",
		trigger = {
			1,
			5270208,
			1
		}
	},
	[926082001] = {
		name = "一决胜负！·后",
		start = 926082001,
		videoPath = "",
		videoType = 1,
		id = 926082001,
		videoId = 0,
		desc = "管理员和尼娅各自端出了料理，薇儿品尝完尼娅的卡达斯炙烤全肉之后表示这次居然真的非常好吃。可当薇儿吃下管理员的料理之后，却连说话的时间都没有，好吃到根本停不下来。尼娅不相信，开始吃管理员做的料理。",
		trigger = {
			1,
			5270208,
			2
		}
	},
	[926091001] = {
		name = "奇谭终幕",
		start = 926091001,
		videoPath = "",
		videoType = 0,
		id = 926091001,
		videoId = 0,
		desc = "吃下料理的尼娅向大家认输，说明了度假小岛上一切异常发生的原因。正当管理员和塞尔凯特打算邀请她加入深空之眼时，她却说自己还有其他事情要做逃走了。晚上，大家一起回到饭堂庆祝任务结束，尼娅来向管理员送上了自己的信物并对管理员告别。",
		trigger = {
			1,
			5270209,
			1
		}
	},
