	[933011001] = {
		name = "来自过去的邀约",
		start = 933011001,
		videoPath = "",
		videoType = 0,
		id = 933011001,
		videoId = 0,
		desc = "薇儿与管理员一同测试弥弥尔系统的同步率，但却进展不大。随后薇儿受过去的同学所邀，带着身为男友的管理员一同参加婚礼，见证了新人们的幸福后，薇儿大为感动，但同时也心生忧虑。",
		trigger = {}
	},
	[933021001] = {
		name = "直达现在的约定",
		start = 933011287,
		videoPath = "",
		videoType = 0,
		id = 933021001,
		videoId = 0,
		desc = "为了解决薇儿的忧虑，管理员与薇儿再度像儿时那般立下约定。或许是拜此所赐，两人的同步率也得以升高，但是离100%还差最后一步，为此——管理员下定了决心。",
		trigger = {}
	},
