		videoPath = "",
		videoType = 0,
		id = 933031001,
		videoId = 0,
		desc = "管理员带着薇儿回到了墨兰德市与薇儿的养父母见面，向他们说明了自己的来意——希望他们能把女儿交给自己。在得到岳父母的首肯后，管理员带着薇儿回到了深空之眼，举行了别开生面的誓约仪式。",
