	[938011001] = {
		name = "出发！新的夏日！",
		start = 938011001,
		videoPath = "",
		videoType = 0,
		id = 938011001,
		videoId = 0,
		desc = "因团建而来到卡达斯乐园度假的第三周，薇儿、大国主、伊邪娜美与埃什聚集在一起商量接下来的时间为管理员准备些什么惊喜，不料正巧被来到餐厅取早餐的管理员听到。正当众人因什么都玩过而苦恼的时候，广播中传出了尼娅的声音，告诉大家即将举办第一届「卡达斯假日赛」。",
		trigger = {}
	},
	[938021001] = {
		name = "卡达斯假日赛？·前",
		start = 938021001,
		videoPath = "",
		videoType = 0,
		id = 938021001,
		videoId = 0,
		desc = "众人来到尼娅创造出来的赛场，得知接下来即将进行赛车比赛，而获胜者将在卡达斯乐园中实现一个愿望。此话一出，众人将管理员团团围住，希望能与他组队，而我则通过抽签的方式，决定了本场比赛的队友——埃克什瓦。",
		trigger = {}
	},
	[938022001] = {
		name = "卡达斯假日赛？·后",
		start = 938022001,
		videoPath = "",
		videoType = 0,
		id = 938022001,
		videoId = 0,
		desc = "第一场比赛过后，众人因为尼娅没有事先告知比赛的真正规则而将她围了起来。于是尼娅想了想，决定将本场比赛记为预赛，同样满足埃什和管理员的愿望。埃什希望大家陪自己演海上荒原剧，而管理员则没有任何愿望，因此，尼娅没收了管理员许愿的权力，直到他找到愿望才能使用。而后尼娅继续举办了正赛的第一场，此时伊邪娜美找上了管理员，希望能和他成为队友。",
		trigger = {}
	},
	[938032001] = {
		name = "正赛第一日",
		start = 938032001,
		videoPath = "",
		videoType = 0,
		id = 938032001,
		videoId = 0,
		desc = "正赛第一场中，神秘的红发少女从天上闯入赛场，造成了混乱，结果被尼娅三拳打晕了过去。众人将她绑在一旁，继续正赛第一场的颁奖许愿仪式。伊邪那美许愿要和管理员约会一整天，而被尼娅没收了许愿权力的管理员也只能看着事情发生。正在这时，克图格娅醒了过来，放出狠话之后，带着她的小弟一起逃离了现场。",
		trigger = {}
	},
	[938041001] = {
		name = "正赛第二日·前",
		start = 938041001,
		videoPath = "",
		videoType = 0,
		id = 938041001,
		videoId = 0,
		desc = "与伊邪娜美共度一晚的管理员失去了很重要的东西，精神萎靡地和大家去吃了早饭。没想到的是，昨天被尼娅揍了的克图格娅竟然大摇大摆地进了餐厅，东张西望似乎在寻找什么，最后居然与大家对上了视线。无奈之下，管理员端起餐盘与克图格娅相互做了自我介绍，简单地认识了一下彼此。紧接着尼娅的声音从广播中传出，正赛第二场即将开始，而管理员决定去找薇儿成为队友。",
		trigger = {}
	},
	[938042001] = {
		name = "正赛第二日·后",
		start = 938042001,
		videoPath = "",
		videoType = 0,
		id = 938042001,
		videoId = 0,
		desc = "管理员与薇儿夺得了比赛冠军，管理员寄希望于薇儿能够夺回自己的睡眠，但没想到薇儿的愿望是管理员能够只看着自己。再一次被夺走睡眠的管理员想一个人稍微静一静，去往了海边，在朝阳般的时刻，管理员遇见了住在海滩边的克图格娅，了解到她来到卡达斯乐园是为了找回自己的权能碎片，于此他们定下了不再捣蛋的诺言，堂堂正正一决胜负。面对管理员的苦恼，克图格娅提出，不如在下一场比赛去找一个更可靠的队友。",
		trigger = {}
	},
	[938051001] = {
		name = "正赛第三日·前",
		start = 938051001,
		videoPath = "",
		videoType = 0,
		id = 938051001,
		videoId = 0,
		desc = "比赛开始前管理员藏在了大国主这里，躲避找来的伊邪娜美和薇儿。于此管理员提出，希望能够与大国主成为队友，赢下下一局比赛。",
		trigger = {}
	},
	[938052001] = {
		name = "正赛第三日·后",
		start = 938052001,
		videoPath = "",
		videoType = 0,
		id = 938052001,
		videoId = 0,
		desc = "正赛第三场之后，大国主许下愿望，为所有人戴上了机械兔耳，一片啾啾声出没于赛场各处。",
		trigger = {}
	},
	[938061001] = {
		name = "正赛第四日·前",
		start = 938061001,
		videoPath = "",
		videoType = 0,
		id = 938061001,
		videoId = 0,
		desc = "凌晨时分，正睡好觉的管理员被大国主叫了起来，原来她的机械兔耳是一个检测器，通过这个检测器，大国主发现克图格娅与尼娅似乎有密不可分的关系，同时更紧急的是，卡达斯王国的时间流速开始变化，如果不及时制止所有人都会被困在乐园里。于是两人找到了克图格娅，希望从她那边找到更多线索。克图格娅对时间流速变慢的事表示毫不知情，并将自己在岛上探索的发现告诉了两人，于是大家目标统一，决定分工行动，一起在正赛第四场中当着所有人的面戳破尼娅的计划。",
		trigger = {}
	},
	[938062001] = {
		name = "正赛第四日·后",
		start = 938062001,
		videoPath = "",
		videoType = 0,
		id = 938062001,
		videoId = 0,
		desc = "管理员与克图格娅获得了第一，他们当着所有人的面质问尼娅的计划和目的。尼娅也不再伪装，说就自己在回收大家在比赛中使用的算力，打算让卡达斯乐园成为永恒的乐园。说完之后，便回到了自己的城堡，而众人开着赛车追了上去。",
		trigger = {}
	},
	[938072001] = {
		name = "我们的愿望",
		start = 938072001,
		videoPath = "",
		videoType = 0,
		id = 938072001,
		videoId = 0,
		desc = "追上尼娅之后，众人在熟悉的魔王城顶开始了决战。尼娅将大家定在了原地，并希望大家能够理解她，然而大家却因乐园之外还有每个人都十分珍惜的生活而拒绝了尼娅的好意。克图格娅趁着大家聊天的间隙，挣脱了束缚，夺回了一部分权能释放了大家。于是众人一拥而上，击败了尼娅。",
		trigger = {}
	},
	[938081001] = {
		name = "假日的尾声",
		start = 938081001,
		videoPath = "",
		videoType = 0,
		id = 938081001,
		videoId = 0,
		desc = "被打败的尼娅将权能还给了克图格娅，并说出了自己真正的目的。本想着这次尼娅应该是要和众人回到深空之眼，但尼娅却说自己有很重要的事情要做，然后逃走了。转眼间，原本还有两周的假期就只剩下了两天，大家都抓紧时间开始实现自己还没做完的愿望，在海边办起了烤肉大会。用餐之后，克图格娅找到了管理员，向管理员表明了心意。跌宕起伏的卡达斯假日赛之后，管理员只剩下了在假期好好睡一觉的渴望。",
		trigger = {}
	}
}
